package cn.workbuddy.r1web;

/**
 * 页面的静态资源（赞赏码 / PWA 三件套）—— 从 device 侧 8088 那一套原样搬过来。
 *
 * <p>为什么必须有：8080 的页面是从 8088 那套复制来的，里面引用了
 * {@code /donate.png}、{@code /manifest.webmanifest}、{@code /sw.js}、
 * {@code /icon-*.png}，而 player 侧 pv1..pv11 只给了一个没有图标的假 manifest
 * ⇒ 赞赏码图片 404、Chrome 拿不到「安装应用」的资格。</p>
 *
 * <p>本文件由 <code>_gen_assets.py</code> 从
 * <code>janus_pandora2/v2src/.../WebConsole.java</code> 抽取生成，
 * 别手改（赞赏码 base64 有 6.5 万字符）。</p>
 */
public final class Assets {

    public static final String DONATE_QR_B64 =
            "" +
            "" +
            ""
            ;

    public static final String MANIFEST_JSON =
            "{\n"
                    + "  \"name\": \"R1 小智控制台\",\n"
                    + "  \"short_name\": \"小智\",\n"
                    + "  \"description\": \"斐讯 R1 音箱 · 小智寄生层控制台\",\n"
                    + "  \"start_url\": \"/\",\n"
                    + "  \"scope\": \"/\",\n"
                    + "  \"display\": \"standalone\",\n"
                    + "  \"orientation\": \"portrait\",\n"
                    + "  \"background_color\": \"#0a0e16\",\n"
                    + "  \"theme_color\": \"#0a0e16\",\n"
                    + "  \"icons\": [\n"
                    + "    {\"src\": \"/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any\"},\n"
                    + "    {\"src\": \"/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any\"},\n"
                    + "    {\"src\": \"/icon-maskable-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"maskable\"}\n"
                    + "  ]\n"
                    + "}\n";

    public static final String SW_JS =
            "var CACHE='r1-shell-v1';\n"
                    + "self.addEventListener('install',function(e){\n"
                    + "  self.skipWaiting();\n"
                    + "  e.waitUntil(caches.open(CACHE).then(function(c){\n"
                    + "    return c.add('/').catch(function(){});\n"
                    + "  }));\n"
                    + "});\n"
                    + "self.addEventListener('activate',function(e){\n"
                    + "  e.waitUntil(caches.keys().then(function(ks){\n"
                    + "    return Promise.all(ks.map(function(k){\n"
                    + "      if(k!==CACHE) return caches.delete(k);\n"
                    + "    }));\n"
                    + "  }).then(function(){ return self.clients.claim(); }));\n"
                    + "});\n"
                    + "self.addEventListener('fetch',function(e){\n"
                    + "  var r=e.request;\n"
                    + "  if(r.method!=='GET') return;\n"
                    + "  var u=new URL(r.url);\n"
                    + "  if(u.origin!==self.location.origin) return;\n"
                    + "  if(u.pathname.indexOf('/api/')===0) return;\n"
                    + "  e.respondWith(fetch(r).then(function(res){\n"
                    + "    var cp=res.clone();\n"
                    + "    caches.open(CACHE).then(function(c){ c.put(r,cp); }).catch(function(){});\n"
                    + "    return res;\n"
                    + "  }).catch(function(){\n"
                    + "    return caches.match(r).then(function(m){ return m||caches.match('/'); });\n"
                    + "  }));\n"
                    + "});\n"
                    + "self.addEventListener('message',function(e){\n"
                    + "  if(e.data==='skip') self.skipWaiting();\n"
                    + "});\n";

    /**
     * 运行时画 PWA 图标 —— 不往 dex 里塞 PNG（192/512 两张得好几 KB）。
     * maskable=true ⇒ 底铺满整张画布、字缩到中心（Android 自适应图标按遮罩裁剪，
     * 安全区只有中心 80%，画满会被切掉角）。
     */
    public static byte[] iconPng(int size, boolean maskable) {
        try {
            android.graphics.Bitmap bmp =
                    android.graphics.Bitmap.createBitmap(size, size,
                            android.graphics.Bitmap.Config.ARGB_8888);
            android.graphics.Canvas cv = new android.graphics.Canvas(bmp);
            android.graphics.Paint p =
                    new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);
            p.setShader(new android.graphics.LinearGradient(0, 0, size, size,
                    0xFF22D3EE, 0xFF818CF8, android.graphics.Shader.TileMode.CLAMP));
            cv.drawRect(0, 0, size, size, p);
            p.reset();
            p.setAntiAlias(true);
            p.setColor(0xFFFFFFFF);
            p.setTypeface(android.graphics.Typeface.create(
                    android.graphics.Typeface.SANS_SERIF, android.graphics.Typeface.BOLD));
            p.setTextAlign(android.graphics.Paint.Align.CENTER);
            p.setTextSize(maskable ? size * 0.30f : size * 0.42f);
            android.graphics.Paint.FontMetrics fm = p.getFontMetrics();
            cv.drawText("R1", size / 2f, size / 2f - (fm.ascent + fm.descent) / 2f, p);
            java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
            bmp.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, bos);
            bmp.recycle();
            return bos.toByteArray();
        } catch (Throwable t) {
            return null;
        }
    }

    private Assets() {
    }
}
